declare(strict_types=1);require __DIR__.'/bootstrap.php';use Ogpn\Bot\{Bootstrap,Auth};$pdo=Bootstrap::pdo();$w=Auth::worker($pdo,'scan.ingest');$b=json_decode(file_get_contents('php://input'),true);if(!is_array($b)||!is_array($b['results']??null))Bootstrap::json(['error'=>'invalid_payload'],422);$pdo->beginTransaction();$up=$pdo->prepare("INSERT INTO domains(domain,tld,http_status,final_url,default_language,selected_language,language_source,language_confidence,analysis_json,first_scanned_at,last_scanned_at) VALUES(?,?,?,?,?,?,?,?,?,UTC_TIMESTAMP(),UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE http_status=VALUES(http_status),final_url=VALUES(final_url),default_language=VALUES(default_language),selected_language=VALUES(selected_language),language_source=VALUES(language_source),language_confidence=VALUES(language_confidence),analysis_json=VALUES(analysis_json),last_scanned_at=UTC_TIMESTAMP()");$q=$pdo->prepare("UPDATE domain_queue SET last_scanned_at=UTC_TIMESTAMP(),next_scan_at=DATE_ADD(UTC_TIMESTAMP(),INTERVAL ? DAY),reserved_by=NULL,reserved_until=NULL,scan_attempts=scan_attempts+1,last_scan_status=? WHERE domain=? AND reserved_by=?");$n=0;foreach($b['results'] as $r){if(!is_array($r)||!isset($r['domain']))continue;$d=(string)$r['domain'];$t=substr(strrchr($d,'.')?:'',1);$status=(int)($r['http_status']??0);$days=$status>=200&&$status<500?30:1;$up->execute([$d,$t,$status,$r['final_url']??null,$r['default_language']??null,$r['selected_language']??null,$r['language_source']??null,$r['language_confidence']??null,json_encode($r['analysis']??[],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);$q->execute([$days,$status?('http_'.$status):'error',$d,$w['worker_id']]);$n++;}$pdo->commit();Bootstrap::json(['ok'=>true,'ingested'=>$n]);
